﻿param(
    [switch]$WriteArtifacts,
    [string]$PriorityPath,
    [string]$CheckpointPath,
    [string]$OutputDirectory
)

$ErrorActionPreference = 'Stop'

function Read-JsonFile {
    param([string]$Path)
    return (Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json)
}

function New-MarkdownReport {
    param([object]$Checklist)
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('# XL Operator Checklist')
    $lines.Add('')
    $lines.Add(('- Generated: {0}' -f $Checklist.generated_at))
    $lines.Add('')
    $lines.Add('## Intake Bands')
    $lines.Add('')
    foreach ($band in @($Checklist.intake_bands)) {
        $lines.Add(('- `{0}` → action=`{1}`, label=`{2}`' -f $band.id, $band.intake_action, $band.decision_label))
    }
    $lines.Add('')
    $lines.Add('## XL Checkpoints')
    $lines.Add('')
    foreach ($checkpoint in @($Checklist.checkpoints)) {
        $lines.Add(('- `{0}` (order `{1}`) — required=`{2}`' -f $checkpoint.id, $checkpoint.stage_order, $checkpoint.required))
    }
    return ($lines -join [Environment]::NewLine)
}

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot '..\..')
if (-not $PriorityPath) { $PriorityPath = Join-Path $repoRoot 'config\skill-intake-priority.json' }
if (-not $CheckpointPath) { $CheckpointPath = Join-Path $repoRoot 'config\xl-operator-checkpoints.json' }
if (-not $OutputDirectory) { $OutputDirectory = Join-Path $repoRoot 'outputs\governance\xl-operator' }

$priority = Read-JsonFile -Path $PriorityPath
$checkpoint = Read-JsonFile -Path $CheckpointPath
$checklist = [pscustomobject]@{
    generated_at = (Get-Date).ToString('s')
    intake_bands = @($priority.bands)
    checkpoints = @($checkpoint.checkpoints)
}

$checklist | ConvertTo-Json -Depth 8

if ($WriteArtifacts) {
    New-Item -ItemType Directory -Force -Path $OutputDirectory | Out-Null
    $jsonPath = Join-Path $OutputDirectory 'xl-operator-checklist.json'
    $mdPath = Join-Path $OutputDirectory 'xl-operator-checklist.md'
    ($checklist | ConvertTo-Json -Depth 8) | Set-Content -LiteralPath $jsonPath -Encoding UTF8
    (New-MarkdownReport -Checklist $checklist) | Set-Content -LiteralPath $mdPath -Encoding UTF8
    Write-Host ('Wrote {0}' -f $jsonPath) -ForegroundColor Green
    Write-Host ('Wrote {0}' -f $mdPath) -ForegroundColor Green
}

param(
    [string]$SourceRoot = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path "third_party\system-prompts-mirror"),
    [string]$OutputPath = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path "outputs\external-corpus\prompt-signals.json"),
    [int]$TopTermsPerFile = 15
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function Get-StopWords {
    return [System.Collections.Generic.HashSet[string]]::new([string[]]@(
        "the", "and", "for", "with", "that", "this", "from", "are", "you", "your", "not", "use", "tool",
        "tools", "json", "txt", "yaml", "yml", "file", "files", "path", "paths", "code", "user", "users",
        "into", "when", "what", "where", "which", "have", "has", "had", "was", "were", "can", "could",
        "should", "would", "will", "must", "may", "their", "they", "them", "then", "than", "only", "also",
        "each", "more", "most", "just", "like", "using", "used", "been", "over", "under", "into", "about",
        "here", "there", "very", "much", "many", "some", "such", "same", "mode", "prompt", "prompts"
    ))
}

function Get-StrategySignals {
    param([string]$TextLower)

    return [pscustomobject]@{
        planning = [bool]($TextLower -match "\b(plan|planning|roadmap|milestone|spec|design)\b")
        execution = [bool]($TextLower -match "\b(implement|execute|run|apply|patch)\b")
        verification = [bool]($TextLower -match "\b(verify|validation|quality gate|assert|check)\b")
        testing = [bool]($TextLower -match "\b(test|unit test|integration test|red green refactor|tdd)\b")
        security = [bool]($TextLower -match "\b(security|vulnerability|safety|owasp|threat)\b")
        fallback = [bool]($TextLower -match "\b(fallback|degraded|retry|graceful)\b")
        routing = [bool]($TextLower -match "\b(route|routing|router|classify|classification|intent)\b")
        multi_agent = [bool]($TextLower -match "\b(subagent|multi-agent|swarm|team orchestration|spawn_agent)\b")
        mcp = [bool]($TextLower -match "\b(mcp|model context protocol|tool schema|input_schema)\b")
    }
}

function Get-TermFrequency {
    param(
        [string]$TextLower,
        [System.Collections.Generic.HashSet[string]]$StopWords
    )

    $result = @{}
    $matches = [Regex]::Matches($TextLower, "[a-z][a-z0-9_/\-]{2,}")
    foreach ($match in $matches) {
        $token = $match.Value
        if ($StopWords.Contains($token)) { continue }
        if (-not $result.ContainsKey($token)) {
            $result[$token] = 0
        }
        $result[$token]++
    }
    return $result
}

function Merge-Frequency {
    param(
        [hashtable]$Target,
        [hashtable]$Incoming
    )

    foreach ($entry in $Incoming.GetEnumerator()) {
        if (-not $Target.ContainsKey($entry.Key)) {
            $Target[$entry.Key] = 0
        }
        $Target[$entry.Key] += [int]$entry.Value
    }
}

function Get-TopTerms {
    param(
        [hashtable]$Frequency,
        [int]$Limit = 15
    )

    return @(
        $Frequency.GetEnumerator() |
        Sort-Object -Property @{ Expression = "Value"; Descending = $true }, @{ Expression = "Key"; Descending = $false } |
        Select-Object -First $Limit |
        ForEach-Object {
            [pscustomobject]@{
                term = [string]$_.Key
                count = [int]$_.Value
            }
        }
    )
}

function Get-RelativePathCompat {
    param(
        [string]$BasePath,
        [string]$TargetPath
    )

    $baseResolved = (Resolve-Path -LiteralPath $BasePath).Path
    $targetResolved = (Resolve-Path -LiteralPath $TargetPath).Path
    if (-not $baseResolved.EndsWith("\")) {
        $baseResolved += "\"
    }

    $baseUri = New-Object System.Uri($baseResolved)
    $targetUri = New-Object System.Uri($targetResolved)
    $relative = [System.Uri]::UnescapeDataString($baseUri.MakeRelativeUri($targetUri).ToString())
    return $relative.Replace("\", "/")
}

if (-not (Test-Path -LiteralPath $SourceRoot)) {
    throw "SourceRoot not found: $SourceRoot"
}

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..\..")
$outputDirectory = Split-Path -Parent $OutputPath
New-Item -ItemType Directory -Path $outputDirectory -Force | Out-Null

$stopWords = Get-StopWords
$globalFrequency = @{}
$fileRecords = New-Object System.Collections.Generic.List[object]
$signalCounts = @{
    planning = 0
    execution = 0
    verification = 0
    testing = 0
    security = 0
    fallback = 0
    routing = 0
    multi_agent = 0
    mcp = 0
}

$sourceExtensions = @(".txt", ".json", ".yaml", ".yml", ".md")
$files = Get-ChildItem -Path $SourceRoot -Recurse -File | Where-Object { $sourceExtensions -contains $_.Extension.ToLowerInvariant() }

foreach ($file in $files) {
    $raw = ""
    try {
        $raw = Get-Content -LiteralPath $file.FullName -Raw -Encoding UTF8
    } catch {
        Write-Warning "Skipping unreadable file: $($file.FullName)"
        continue
    }

    if ([string]::IsNullOrWhiteSpace($raw)) { continue }

    $relativePath = Get-RelativePathCompat -BasePath $SourceRoot -TargetPath $file.FullName
    $segments = $relativePath.Split("/")
    $vendor = if ($segments.Count -gt 0) { $segments[0] } else { "unknown" }
    $textLower = $raw.ToLowerInvariant()

    $localFrequency = Get-TermFrequency -TextLower $textLower -StopWords $stopWords
    Merge-Frequency -Target $globalFrequency -Incoming $localFrequency
    $topTerms = Get-TopTerms -Frequency $localFrequency -Limit $TopTermsPerFile
    $signals = Get-StrategySignals -TextLower $textLower

    foreach ($name in @("planning", "execution", "verification", "testing", "security", "fallback", "routing", "multi_agent", "mcp")) {
        if ($signals.$name) {
            $signalCounts[$name]++
        }
    }

    $fileRecords.Add([pscustomobject]@{
        vendor = $vendor
        relative_path = $relativePath
        extension = $file.Extension.ToLowerInvariant()
        size_bytes = [int64]$file.Length
        strategy_signals = $signals
        top_terms = $topTerms
    })
}

$vendorStats = @(
    $fileRecords |
    Group-Object -Property vendor |
    Sort-Object -Property Count -Descending |
    ForEach-Object {
        [pscustomobject]@{
            vendor = [string]$_.Name
            file_count = [int]$_.Count
        }
    }
)

$result = [pscustomobject]@{
    version = 1
    generated_at = (Get-Date).ToUniversalTime().ToString("o")
    source_root = $SourceRoot
    file_count = [int]$fileRecords.Count
    vendor_count = [int]$vendorStats.Count
    signal_counts = [pscustomobject]$signalCounts
    vendors = $vendorStats
    token_frequency = (Get-TopTerms -Frequency $globalFrequency -Limit 400)
    files = $fileRecords
}

$result | ConvertTo-Json -Depth 9 | Set-Content -LiteralPath $OutputPath -Encoding UTF8

Write-Host "Extracted signals from $($result.file_count) files."
Write-Host "Output: $OutputPath"

param(
    [string]$SignalPath = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path "outputs\external-corpus\prompt-signals.json"),
    [string]$SourceRoot = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path "third_party\system-prompts-mirror"),
    [string]$SkillIndexPath = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path "config\skill-keyword-index.json"),
    [string]$PackManifestPath = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path "config\pack-manifest.json"),
    [string]$OutputDirectory = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path "outputs\external-corpus"),
    [int]$MinPhraseHits = 3,
    [int]$MaxKeywordsPerSkill = 8
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function New-PhraseRule {
    param(
        [string]$Skill,
        [string]$Phrase,
        [string]$Regex
    )

    return [pscustomobject]@{
        skill = $Skill
        phrase = $Phrase
        regex = $Regex
    }
}

function Count-Matches {
    param(
        [string[]]$Texts,
        [string]$Regex
    )

    $count = 0
    foreach ($text in $Texts) {
        $count += [Regex]::Matches($text, $Regex).Count
    }
    return $count
}

if (-not (Test-Path -LiteralPath $SignalPath)) {
    throw "Signal file not found: $SignalPath. Run extract-prompt-signals.ps1 first."
}
if (-not (Test-Path -LiteralPath $SkillIndexPath)) {
    throw "Skill index not found: $SkillIndexPath"
}
if (-not (Test-Path -LiteralPath $PackManifestPath)) {
    throw "Pack manifest not found: $PackManifestPath"
}
if (-not (Test-Path -LiteralPath $SourceRoot)) {
    throw "Source root not found: $SourceRoot"
}

New-Item -ItemType Directory -Path $OutputDirectory -Force | Out-Null

$signals = Get-Content -LiteralPath $SignalPath -Raw -Encoding UTF8 | ConvertFrom-Json
$skillIndex = Get-Content -LiteralPath $SkillIndexPath -Raw -Encoding UTF8 | ConvertFrom-Json
$packManifest = Get-Content -LiteralPath $PackManifestPath -Raw -Encoding UTF8 | ConvertFrom-Json

$scanExtensions = @(".txt", ".json", ".yaml", ".yml", ".md")
$corpusTexts = @(
    Get-ChildItem -Path $SourceRoot -Recurse -File |
    Where-Object { $scanExtensions -contains $_.Extension.ToLowerInvariant() } |
    ForEach-Object {
        try {
            (Get-Content -LiteralPath $_.FullName -Raw -Encoding UTF8).ToLowerInvariant()
        } catch {
            ""
        }
    } |
    Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
)

$phraseRules = @(
    (New-PhraseRule -Skill "vibe" -Phrase "tool selection" -Regex "\btool selection\b")
    (New-PhraseRule -Skill "vibe" -Phrase "task classification" -Regex "\btask classification\b")
    (New-PhraseRule -Skill "vibe" -Phrase "agent orchestration" -Regex "\bagent orchestration\b")
    (New-PhraseRule -Skill "subagent-driven-development" -Phrase "multi-agent workflow" -Regex "\bmulti-agent workflow\b")
    (New-PhraseRule -Skill "subagent-driven-development" -Phrase "parallel agents" -Regex "\bparallel agents?\b")
    (New-PhraseRule -Skill "systematic-debugging" -Phrase "root cause investigation" -Regex "\broot cause investigation\b")
    (New-PhraseRule -Skill "systematic-debugging" -Phrase "failure analysis" -Regex "\bfailure analysis\b")
    (New-PhraseRule -Skill "tdd-guide" -Phrase "red green refactor" -Regex "\bred green refactor\b")
    (New-PhraseRule -Skill "tdd-guide" -Phrase "test-first development" -Regex "\btest[- ]first development\b")
    (New-PhraseRule -Skill "code-reviewer" -Phrase "risk assessment" -Regex "\brisk assessment\b")
    (New-PhraseRule -Skill "code-reviewer" -Phrase "behavioral regression" -Regex "\bbehavioral regression\b")
    (New-PhraseRule -Skill "security-reviewer" -Phrase "defensive security" -Regex "\bdefensive security\b")
    (New-PhraseRule -Skill "security-reviewer" -Phrase "threat model" -Regex "\bthreat model\b")
    (New-PhraseRule -Skill "mcp-integration" -Phrase "tool schema" -Regex "\btool schema\b")
    (New-PhraseRule -Skill "mcp-integration" -Phrase "input schema" -Regex "\binput_schema\b|\binput schema\b")
    (New-PhraseRule -Skill "openai-docs" -Phrase "codex cli" -Regex "\bcodex cli\b")
    (New-PhraseRule -Skill "openai-docs" -Phrase "chat completions" -Regex "\bchat completions\b")
    (New-PhraseRule -Skill "openai-knowledge" -Phrase "responses api" -Regex "\bresponses api\b")
    (New-PhraseRule -Skill "documentation-lookup" -Phrase "api reference" -Regex "\bapi reference\b")
    (New-PhraseRule -Skill "prompt-lookup" -Phrase "system prompt" -Regex "\bsystem prompt\b")
    (New-PhraseRule -Skill "prompt-lookup" -Phrase "prompt template" -Regex "\bprompt template\b")
)

$existingSkillNames = @($skillIndex.skills.PSObject.Properties.Name)
$skillAdditions = @{}
$ruleResults = New-Object System.Collections.Generic.List[object]

foreach ($rule in $phraseRules) {
    $hits = Count-Matches -Texts $corpusTexts -Regex $rule.regex
    $existsInSkillIndex = $existingSkillNames -contains $rule.skill

    $alreadyPresent = $false
    if ($existsInSkillIndex) {
        $keywords = @($skillIndex.skills.($rule.skill).keywords)
        $alreadyPresent = $keywords -contains $rule.phrase
    }

    $accepted = $existsInSkillIndex -and (-not $alreadyPresent) -and ($hits -ge $MinPhraseHits)
    if ($accepted) {
        if (-not $skillAdditions.ContainsKey($rule.skill)) {
            $skillAdditions[$rule.skill] = New-Object System.Collections.Generic.List[string]
        }
        $skillAdditions[$rule.skill].Add($rule.phrase)
    }

    $ruleResults.Add([pscustomobject]@{
        skill = $rule.skill
        phrase = $rule.phrase
        regex = $rule.regex
        hits = [int]$hits
        exists_in_skill_index = $existsInSkillIndex
        already_present = $alreadyPresent
        accepted = $accepted
    })
}

# Build candidate skill index with conservative additions.
$candidateSkillIndex = $skillIndex | ConvertTo-Json -Depth 100 | ConvertFrom-Json
$appliedCount = 0
foreach ($skillName in $skillAdditions.Keys) {
    $currentKeywords = @($candidateSkillIndex.skills.($skillName).keywords)
    $toAdd = @($skillAdditions[$skillName] | Sort-Object -Unique | Select-Object -First $MaxKeywordsPerSkill)
    foreach ($kw in $toAdd) {
        if ($currentKeywords -contains $kw) { continue }
        $currentKeywords += $kw
        $appliedCount++
    }
    $candidateSkillIndex.skills.($skillName).keywords = $currentKeywords
}

# Pack-level suggestions (advisory only; not auto-applied).
$packSuggestions = New-Object System.Collections.Generic.List[object]
foreach ($pack in $packManifest.packs) {
    $packKeywords = @($pack.trigger_keywords | ForEach-Object { $_.ToLowerInvariant() })
    $tokenHints = @(
        $signals.token_frequency |
        ForEach-Object { $_.term } |
        Where-Object { $_ -match "agent|debug|review|route|workflow|security|test|model|prompt|mcp" } |
        Select-Object -Unique |
        Select-Object -First 20
    )

    $missing = @($tokenHints | Where-Object { $packKeywords -notcontains $_ })
    $packSuggestions.Add([pscustomobject]@{
        pack_id = $pack.id
        advisory_trigger_candidates = @($missing | Select-Object -First 10)
    })
}

$summary = [pscustomobject]@{
    source_root = $SourceRoot
    signal_file = $SignalPath
    corpus_file_count = [int]$signals.file_count
    rules_evaluated = [int]$ruleResults.Count
    phrases_accepted = [int]($ruleResults | Where-Object { $_.accepted }).Count
    skill_keywords_added = $appliedCount
}

$suggestionObject = [pscustomobject]@{
    version = 1
    generated_at = (Get-Date).ToUniversalTime().ToString("o")
    summary = $summary
    skill_rule_results = $ruleResults
    skill_additions = @(
        $skillAdditions.GetEnumerator() | ForEach-Object {
            [pscustomobject]@{
                skill = [string]$_.Key
                additions = @($_.Value | Sort-Object -Unique)
            }
        }
    )
    pack_suggestions = $packSuggestions
}

$suggestionJsonPath = Join-Path $OutputDirectory "vco-suggestions.json"
$suggestionMdPath = Join-Path $OutputDirectory "vco-suggestions.md"
$candidateIndexPath = Join-Path $OutputDirectory "skill-keyword-index.candidate.json"

$suggestionObject | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $suggestionJsonPath -Encoding UTF8
$candidateSkillIndex | ConvertTo-Json -Depth 100 | Set-Content -LiteralPath $candidateIndexPath -Encoding UTF8

$md = New-Object System.Text.StringBuilder
[void]$md.AppendLine("# VCO External Corpus Suggestions")
[void]$md.AppendLine("")
[void]$md.AppendLine("- Generated: $($suggestionObject.generated_at)")
[void]$md.AppendLine("- Source root: $SourceRoot")
[void]$md.AppendLine("- Corpus files scanned: $($summary.corpus_file_count)")
[void]$md.AppendLine("- Rules evaluated: $($summary.rules_evaluated)")
[void]$md.AppendLine("- Accepted phrases: $($summary.phrases_accepted)")
[void]$md.AppendLine("- Candidate skill keywords added: $($summary.skill_keywords_added)")
[void]$md.AppendLine("")
[void]$md.AppendLine("## Skill Additions")
[void]$md.AppendLine("")

$skillAdditionRows = @($suggestionObject.skill_additions)
if ($skillAdditionRows.Count -eq 0) {
    [void]$md.AppendLine("No safe additions met the threshold.")
} else {
    foreach ($entry in $skillAdditionRows) {
        [void]$md.AppendLine("- `$($entry.skill)`: $([string]::Join(", ", $entry.additions))")
    }
}

[void]$md.AppendLine("")
[void]$md.AppendLine("## Advisory Pack Trigger Candidates")
[void]$md.AppendLine("")
foreach ($entry in $suggestionObject.pack_suggestions) {
    [void]$md.AppendLine("- `$($entry.pack_id)`: $([string]::Join(", ", $entry.advisory_trigger_candidates))")
}

$md.ToString() | Set-Content -LiteralPath $suggestionMdPath -Encoding UTF8

Write-Host "Suggestions JSON: $suggestionJsonPath"
Write-Host "Suggestions Markdown: $suggestionMdPath"
Write-Host "Candidate skill index: $candidateIndexPath"

﻿param(
    [string]$SourceRoot = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..\..')) 'third_party\vco-ecosystem-mirror\awesome-mcp-servers'),
    [string]$OutputPath = (Join-Path (Resolve-Path (Join-Path $PSScriptRoot '..\..')) 'outputs\research\awesome-mcp-servers.snapshot.json')
)

$ErrorActionPreference = "Stop"

function Get-LanguageTag {
    param([string]$Name)

    if ($Name -ieq 'README.md') { return 'en' }
    if ($Name -match '^README-(.+)\.md$') { return $Matches[1] }
    return 'unknown'
}

function Get-GitHubRepoFromUrl {
    param([string]$Url)

    try {
        $uri = [System.Uri]$Url
        if ($uri.Host -notmatch 'github\.com$') { return $null }
        $segments = @($uri.AbsolutePath.Trim('/').Split('/'))
        if ($segments.Count -lt 2) { return $null }
        return ('{0}/{1}' -f $segments[0], $segments[1])
    } catch {
        return $null
    }
}

$sourceRootResolved = Resolve-Path $SourceRoot
$readmes = @(Get-ChildItem -LiteralPath $sourceRootResolved -File -Filter 'README*.md' | Sort-Object Name)
if ($readmes.Count -eq 0) {
    throw "No README*.md files found under $sourceRootResolved"
}

$entries = New-Object System.Collections.Generic.List[object]
$sourceFiles = @()

foreach ($readme in $readmes) {
    $sourceFiles += [string]$readme.FullName
    $headings = @()
    $lineNumber = 0
    foreach ($line in Get-Content -LiteralPath $readme.FullName -Encoding UTF8) {
        $lineNumber += 1

        if ($line -match '^(#{1,6})\s+(.+?)\s*$') {
            $level = $Matches[1].Length
            $title = $Matches[2].Trim()
            if ($headings.Count -ge $level) {
                $headings = @($headings[0..($level - 2)])
            }
            $headings += $title
            continue
        }

        if ($line -match '^\s*[-*+]\s+.*?\[(?<label>[^\]]+)\]\((?<url>https?://[^)\s]+)\)') {
            $url = $Matches['url']
            $label = $Matches['label'].Trim()
            try {
                $urlHost = ([System.Uri]$url).Host
            } catch {
                $urlHost = $null
            }

            $entries.Add([ordered]@{
                readme = [string]$readme.Name
                language = Get-LanguageTag -Name $readme.Name
                line = $lineNumber
                section = $(if ($headings.Count -gt 0) { $headings[-1] } else { $null })
                section_path = $(if ($headings.Count -gt 0) { $headings -join ' > ' } else { $null })
                label = $label
                url = $url
                host = $urlHost
                github_repo = Get-GitHubRepoFromUrl -Url $url
            }) | Out-Null
        }
    }
}

$outputObject = [pscustomobject]@{
    generated_at = [DateTime]::UtcNow.ToString('o')
    source_root = [string]$sourceRootResolved
    source_files = [string[]]@($sourceFiles)
    readme_count = $readmes.Count
    entry_count = $entries.Count
    generation_policy = 'snapshot-only; does not mutate config/tool-registry.json'
    sample_entries = [object[]]($entries | Select-Object -First 5)
    entries = [object[]]$entries.ToArray()
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $OutputPath) | Out-Null
$outputObject | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $OutputPath -Encoding UTF8

Write-Host '=== MCP Catalog Sync ===' -ForegroundColor Cyan
Write-Host ("Source root : {0}" -f $sourceRootResolved)
Write-Host ("README count: {0}" -f $readmes.Count)
Write-Host ("Entry count : {0}" -f $entries.Count)
Write-Host ("Output      : {0}" -f $OutputPath)

param(
    [string]$TelemetryDirectory,
    [string]$OutputJsonPath,
    [string]$OutputMarkdownPath,
    [int]$LookbackDays = 7
)

$ErrorActionPreference = "Stop"

function Resolve-DefaultPaths {
    param(
        [string]$RepoRoot,
        [object]$ObservabilityPolicy
    )

    $telemetryRel = "outputs/telemetry"
    $jsonRel = "outputs/learn/vibe-adaptive-suggestions.json"
    $mdRel = "outputs/learn/vibe-adaptive-suggestions.md"

    if ($ObservabilityPolicy -and $ObservabilityPolicy.telemetry -and $ObservabilityPolicy.telemetry.output_dir) {
        $telemetryRel = [string]$ObservabilityPolicy.telemetry.output_dir
    }
    if ($ObservabilityPolicy -and $ObservabilityPolicy.learning -and $ObservabilityPolicy.learning.output_path) {
        $jsonRel = [string]$ObservabilityPolicy.learning.output_path
        if ($jsonRel.EndsWith(".json")) {
            $mdRel = $jsonRel.Substring(0, $jsonRel.Length - 5) + ".md"
        }
    }

    return [pscustomobject]@{
        telemetry = Join-Path $RepoRoot $telemetryRel
        json = Join-Path $RepoRoot $jsonRel
        markdown = Join-Path $RepoRoot $mdRel
    }
}

function Get-GroupStats {
    param(
        [object[]]$Events,
        [double]$MinTopGap
    )

    $groups = $Events | Group-Object -Property scenario_key
    $rows = @()
    foreach ($g in $groups) {
        $items = @($g.Group)
        $count = $items.Count
        if ($count -le 0) { continue }

        $legacy = ($items | Where-Object { $_.route.route_mode -eq "legacy_fallback" }).Count
        $confirm = ($items | Where-Object { $_.route.route_mode -eq "confirm_required" }).Count
        $lowGap = ($items | Where-Object { [double]$_.route.top1_top2_gap -lt $MinTopGap }).Count
        $confidenceValues = @(
            $items | ForEach-Object {
                if ($_.route -and $_.route.confidence -ne $null) {
                    [double]$_.route.confidence
                } else {
                    0.0
                }
            }
        )
        $gapValues = @(
            $items | ForEach-Object {
                if ($_.route -and $_.route.top1_top2_gap -ne $null) {
                    [double]$_.route.top1_top2_gap
                } else {
                    0.0
                }
            }
        )

        $avgConfidenceRaw = if ($confidenceValues.Count -gt 0) { ($confidenceValues | Measure-Object -Average).Average } else { 0.0 }
        $avgGapRaw = if ($gapValues.Count -gt 0) { ($gapValues | Measure-Object -Average).Average } else { 0.0 }
        $avgConfidence = [Math]::Round([double]$avgConfidenceRaw, 4)
        $avgGap = [Math]::Round([double]$avgGapRaw, 4)

        $rows += [pscustomobject]@{
            scenario_key = [string]$g.Name
            event_count = $count
            legacy_fallback_rate = [Math]::Round(($legacy / $count), 4)
            confirm_required_rate = [Math]::Round(($confirm / $count), 4)
            low_gap_rate = [Math]::Round(($lowGap / $count), 4)
            avg_confidence = $avgConfidence
            avg_top_gap = $avgGap
            environment_profile_id = [string]$items[0].environment_profile_id
            user_profile_id = [string]$items[0].user_profile_id
            task_type = [string]$items[0].route.task_type
        }
    }
    return $rows
}

function Build-Recommendations {
    param(
        [object[]]$GroupStats,
        [object]$Thresholds,
        [object]$ObservabilityPolicy
    )

    $current = $Thresholds.thresholds
    $minEvents = 200
    if ($ObservabilityPolicy -and $ObservabilityPolicy.learning -and $ObservabilityPolicy.learning.min_events_for_suggestion -ne $null) {
        $minEvents = [int]$ObservabilityPolicy.learning.min_events_for_suggestion
    }

    $maxDeltaConfirm = 0.03
    $maxDeltaGap = 0.03
    $maxDeltaFallback = 0.02
    if ($ObservabilityPolicy -and $ObservabilityPolicy.learning -and $ObservabilityPolicy.learning.bounded_adjustments) {
        $adj = $ObservabilityPolicy.learning.bounded_adjustments
        if ($adj.confirm_required_max_delta -ne $null) { $maxDeltaConfirm = [double]$adj.confirm_required_max_delta }
        if ($adj.min_top_gap_max_delta -ne $null) { $maxDeltaGap = [double]$adj.min_top_gap_max_delta }
        if ($adj.fallback_threshold_max_delta -ne $null) { $maxDeltaFallback = [double]$adj.fallback_threshold_max_delta }
    }

    $rec = @()
    foreach ($row in $GroupStats) {
        if ($row.event_count -lt $minEvents) { continue }

        if ($row.legacy_fallback_rate -ge 0.35 -and $row.avg_confidence -ge ([double]$current.fallback_to_legacy_below + 0.05)) {
            $delta = [Math]::Min($maxDeltaFallback, 0.02)
            $target = [Math]::Round(([double]$current.fallback_to_legacy_below - $delta), 4)
            $rec += [pscustomobject]@{
                scenario_key = $row.scenario_key
                reason = "high_legacy_fallback_with_confident_scores"
                parameter = "thresholds.fallback_to_legacy_below"
                current_value = [double]$current.fallback_to_legacy_below
                suggested_value = $target
                delta = -$delta
                apply_policy = "manual_review_required"
            }
        }

        if ($row.confirm_required_rate -ge 0.5 -and $row.avg_top_gap -ge ([double]$current.min_top1_top2_gap + 0.08)) {
            $delta = [Math]::Min($maxDeltaConfirm, 0.02)
            $target = [Math]::Round(([double]$current.confirm_required - $delta), 4)
            $rec += [pscustomobject]@{
                scenario_key = $row.scenario_key
                reason = "high_confirm_required_with_clear_top_gap"
                parameter = "thresholds.confirm_required"
                current_value = [double]$current.confirm_required
                suggested_value = $target
                delta = -$delta
                apply_policy = "manual_review_required"
            }
        }

        if ($row.low_gap_rate -ge 0.35) {
            $delta = [Math]::Min($maxDeltaGap, 0.01)
            $target = [Math]::Round(([double]$current.min_top1_top2_gap + $delta), 4)
            $rec += [pscustomobject]@{
                scenario_key = $row.scenario_key
                reason = "persistent_low_top1_top2_gap"
                parameter = "thresholds.min_top1_top2_gap"
                current_value = [double]$current.min_top1_top2_gap
                suggested_value = $target
                delta = $delta
                apply_policy = "manual_review_required"
            }
        }
    }

    return $rec
}

$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..\..")
$obsPolicyPath = Join-Path $repoRoot "config/observability-policy.json"
$routerThresholdPath = Join-Path $repoRoot "config/router-thresholds.json"
$obsPolicy = if (Test-Path -LiteralPath $obsPolicyPath) { Get-Content -LiteralPath $obsPolicyPath -Raw -Encoding UTF8 | ConvertFrom-Json } else { $null }
$thresholds = Get-Content -LiteralPath $routerThresholdPath -Raw -Encoding UTF8 | ConvertFrom-Json
$defaults = Resolve-DefaultPaths -RepoRoot $repoRoot -ObservabilityPolicy $obsPolicy

if (-not $TelemetryDirectory) { $TelemetryDirectory = $defaults.telemetry }
if (-not $OutputJsonPath) { $OutputJsonPath = $defaults.json }
if (-not $OutputMarkdownPath) { $OutputMarkdownPath = $defaults.markdown }

$cutoffDate = (Get-Date).AddDays(-1 * [Math]::Abs($LookbackDays))
$files = @()
if (Test-Path -LiteralPath $TelemetryDirectory) {
    $files = Get-ChildItem -LiteralPath $TelemetryDirectory -Filter "route-events-*.jsonl" -File | Where-Object { $_.LastWriteTime -ge $cutoffDate }
}

$events = @()
foreach ($file in $files) {
    $lines = Get-Content -LiteralPath $file.FullName -Encoding UTF8
    foreach ($line in $lines) {
        if ([string]::IsNullOrWhiteSpace($line)) { continue }
        try {
            $events += ($line | ConvertFrom-Json)
        } catch {
            continue
        }
    }
}

$groupStats = Get-GroupStats -Events $events -MinTopGap ([double]$thresholds.thresholds.min_top1_top2_gap)
$recommendations = Build-Recommendations -GroupStats $groupStats -Thresholds $thresholds -ObservabilityPolicy $obsPolicy

$summary = [pscustomobject]@{
    generated_at = (Get-Date).ToString("s")
    lookback_days = [int]$LookbackDays
    telemetry_directory = (Resolve-Path -LiteralPath $TelemetryDirectory -ErrorAction SilentlyContinue | ForEach-Object { $_.Path })
    files_scanned = @($files | Select-Object -ExpandProperty FullName)
    total_events = $events.Count
    scenarios = $groupStats.Count
    min_events_for_suggestion = if ($obsPolicy -and $obsPolicy.learning) { [int]$obsPolicy.learning.min_events_for_suggestion } else { 200 }
    apply_policy = if ($obsPolicy -and $obsPolicy.learning -and $obsPolicy.learning.apply_policy) { [string]$obsPolicy.learning.apply_policy } else { "manual_review_required" }
    recommendations = $recommendations
    scenario_stats = $groupStats
}

$jsonDir = Split-Path -Parent $OutputJsonPath
$mdDir = Split-Path -Parent $OutputMarkdownPath
New-Item -ItemType Directory -Path $jsonDir -Force | Out-Null
New-Item -ItemType Directory -Path $mdDir -Force | Out-Null

$summary | ConvertTo-Json -Depth 30 | Set-Content -LiteralPath $OutputJsonPath -Encoding UTF8

$lines = @()
$lines += "# VCO Adaptive Suggestions (Offline)"
$lines += ""
$lines += "- generated_at: ``$($summary.generated_at)``"
$lines += "- lookback_days: ``$($summary.lookback_days)``"
$lines += "- total_events: ``$($summary.total_events)``"
$lines += "- scenarios: ``$($summary.scenarios)``"
$lines += "- recommendation_count: ``$($recommendations.Count)``"
$lines += "- apply_policy: ``$($summary.apply_policy)``"
$lines += ""
$lines += "## Recommendations"
$lines += ""

if ($recommendations.Count -eq 0) {
    $lines += "- No threshold adjustments suggested for current telemetry window."
} else {
    foreach ($r in $recommendations) {
        $lines += "- scenario=``$($r.scenario_key)`` param=``$($r.parameter)`` current=``$($r.current_value)`` suggested=``$($r.suggested_value)`` reason=``$($r.reason)``"
    }
}

$lines -join "`n" | Set-Content -LiteralPath $OutputMarkdownPath -Encoding UTF8

[pscustomobject]@{
    ok = $true
    output_json = $OutputJsonPath
    output_markdown = $OutputMarkdownPath
    total_events = $events.Count
    recommendations = $recommendations.Count
} | ConvertTo-Json -Depth 10
